"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[98692],{98692:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/seven-people-one-role.png\\"\\n          title=\\"7인 1역\\"\\n          author=\\"렌죠 미키히코\\"\\n          publisher=\\"모모\\"\\n          publishedDate=\\"2023-12-01\\"\\n          isbn=\\"9791193358078\\"\\n          rating=4.5\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\n책 제목에 끌려서 읽게 되었다.  \\n```렌죠 미키히코```는 <mark>백광</mark>이라는 책을 통해 이미 알고 있었다.  \\n사실 백광은 아주 재미있었다 정도는 아니어서 작가에 대한 큰 기대는 하지 않고 읽었다.  \\n<br>\\n```나는 일곱 번 살해되었다``` 이 문장 하나로 이 책은 설명이 된다.  \\n책 제목이 1인 7역이 아니라 <mark>7인 1역</mark>인 이유를 찾는 트릭 찾기 책이었다.  \\n<br>\\n용의자들 각각의 시점에서 나오는 고백과 착각이 독자들에게 점점 더 혼돈을 준다는 부분에서 흥미롭고 재미있게 술술 읽히는 책이었다.  \\n```렌죠 미키히코```의 다른 작품도 읽어봐야겠다."}')}}]);